    void testCompoundOps()
    {
        auto m = gocpp::make(gocpp::Tag<gocpp::map<gocpp::string, int64_t>>());
        m.ref("inc"_s)++;
        m.ref("dec"_s)--;
        m.ref("add"_s) += 5;
        m.ref("sub"_s) -= 3;
        m.ref("or"_s) |= 4;
        // writes a zero, but must still insert the key
        m.ref("shl"_s) <<= 2;
        mocklib::Println(m, len(m));

        auto s = gocpp::make(gocpp::Tag<gocpp::map<gocpp::string, gocpp::string>>());
        s.ref("k"_s) += "x"_s;
        s.ref("k"_s) += "y"_s;
        mocklib::Println(s);
    }

